// Package ice_analyzer 基于回波强度序列计算海冰密集度并识别冰脊位置。
package ice_analyzer

import "icebreaker-radar/internal/echo_parser"

// Config 为分析阈值配置。
type Config struct {
	// IceThreshold 判定某采样点为海冰的回波强度阈值（0-65535）。
	IceThreshold uint16
	// RidgeThreshold 判定冰脊峰值的回波强度阈值。
	RidgeThreshold uint16
